use vstd::prelude::*;

verus! {
    // Specification for checking if an integer is odd
    spec fn is_odd(x: i32) -> bool {
        x % 2 != 0
    }

    // Function to find the first odd element in the array
    fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
        ensures
            found ==> (index < a.len() && is_odd(a[index])),
            !found ==> (index == 0),
    {
        let mut idx: usize = 0;
        let len = a.len();
        while idx < len
            invariant
                idx <= len,
                forall |j: usize| j < idx ==> (a[j] % 2 == 0),
        {
            if is_odd(a[idx]) {
                return (true, idx);
            }
            idx = idx + 1;
        }
        (false, 0) // If no odd element is found, return (false, 0)
    }
}

